import{_ as e,c as l,o as i,ah as r}from"./chunks/framework.Dnh4IO1K.js";const b=JSON.parse('{"title":"风地观","description":"周易折中 - 风地观","frontmatter":{"title":"风地观","description":"周易折中 - 风地观"},"headers":[],"relativePath":"zh/classics/zhezhong/026.md","filePath":"zh/classics/zhezhong/026.md"}'),h={name:"zh/classics/zhezhong/026.md"};function p(n,a,d,t,s,o){return i(),l("div",null,[...a[0]||(a[0]=[r('<h1 id="风地观" tabindex="-1">风地观 <a class="header-anchor" href="#风地观" aria-label="Permalink to “风地观”">​</a></h1><h3 id="程传" tabindex="-1">程传 <a class="header-anchor" href="#程传" aria-label="Permalink to “程传”">​</a></h3><p>观序卦：临者大也，物大然后可观，故受之以观。观所以次临也。凡观视于物，则为观；为观于下，则为观，如楼观谓之观者，为观于下也。人君上观天道，下观民俗，则为观；修德行政，为民瞻仰，则为观。风行地上，遍触万类，周观之象也。二阳在上，四阴在下，阳刚居尊，为群下所观仰，观之义也。在诸爻，则唯取观见，随时为义也。</p><p>观：盥而不荐，有孚颙若</p><h3 id="本义" tabindex="-1">本义 <a class="header-anchor" href="#本义" aria-label="Permalink to “本义”">​</a></h3><p>观者有以示人而为人所仰也。九五居上，四阴仰之，又内顺外巽，而九五以中正示天下，所以为观。盥，将祭而洁手也；荐，奉酒食以祭也。颙然，尊敬之貌。言致其洁清而不轻自用，则其孚信在中而颙然可仰。戒占者宜如是也。或曰有孚颙若，谓在下之人信而仰之也。此卦四阴长而二阳消，正为八月之卦，而名卦繋辞更取他义，亦扶阳抑阴之意。</p><h3 id="程传-1" tabindex="-1">程传 <a class="header-anchor" href="#程传-1" aria-label="Permalink to “程传”">​</a></h3><p>予闻之胡翼之先生曰：君子居上为天下之表仪，必极其庄敬，则下观仰而化也。故为天下之观，当如宗庙之祭，始盥之时，不可如既荐之后，则下民尽其至诚，颙然瞻仰之矣。盥谓祭祀之始，盥手酌郁鬯于地求神之时也；荐谓献腥献熟之时也。盥者事之始，人心方尽其精诚，严肃之至也；至既荐之后，礼数繁缛，则人心散而精一不若始盥之时矣。居上者正其表仪以为下民之观，当庄严如始盥之初，勿使诚意少散如既荐之后，则天下之人莫不尽其孚诚，颙然瞻仰之矣。颙，仰望也。</p><h3 id="集说" tabindex="-1">集说 <a class="header-anchor" href="#集说" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>朱子语类云：自上示下曰观，自下观上曰观，故卦名之“观”去声，而六爻之“观”皆平声。 或问：伊川以为灌鬯之初，诚意犹存，至荐羞之后，精意懈怠；本义以为致其洁清而不轻自用，其义不同。 曰：盥只是浣手，不是灌鬯。伊川承先儒之误。若云荐羞之后，诚意懈怠，则先王祭祀只是灌鬯之初犹有诚意，及荐羞之后皆不成礼矣。问若尔，则是圣人在上，视听言动皆当为天下法而不敢轻，亦犹祭祀之时致其洁清而不敢轻用否？曰然。 又云：祭祀无不荐者，此是假设来说。荐是用事了，盥是未用事之初。云“不荐”者，言常持得这诚敬如盥之意常在。若荐则是用出，用出则才毕便过了，无复有初意矣。 问：“有孚颙若”承上文“盥而不荐”，盖致其洁清而不轻自用，则孚信在中而颙然可仰。一说下之人信而仰之。二说孰长？曰从后说则合得彖辞“下观而化”之义。问前说似好？ 曰：当以彖辞为定。</p></li><li><p>自上示下曰观，自下观上曰观，故卦名之“观”去声，而六爻之“观”皆平声。</p></li><li><p>或问：伊川以为灌鬯之初，诚意犹存，至荐羞之后，精意懈怠；本义以为致其洁清而不轻自用，其义不同。 曰：盥只是浣手，不是灌鬯。伊川承先儒之误。若云荐羞之后，诚意懈怠，则先王祭祀只是灌鬯之初犹有诚意，及荐羞之后皆不成礼矣。问若尔，则是圣人在上，视听言动皆当为天下法而不敢轻，亦犹祭祀之时致其洁清而不敢轻用否？曰然。</p></li><li><p>又云：祭祀无不荐者，此是假设来说。荐是用事了，盥是未用事之初。云“不荐”者，言常持得这诚敬如盥之意常在。若荐则是用出，用出则才毕便过了，无复有初意矣。</p></li><li><p>问：“有孚颙若”承上文“盥而不荐”，盖致其洁清而不轻自用，则孚信在中而颙然可仰。一说下之人信而仰之。二说孰长？曰从后说则合得彖辞“下观而化”之义。问前说似好？ 曰：当以彖辞为定。</p></li><li><p>冯氏椅曰：卦叠艮之画，有门阙重复之象，故取象于观。</p></li><li><p>龚氏焕曰：易之名卦以阳为主，在阳长之卦固主于阳而言，在阴长之卦亦主于阳而言。主于阳而言者，所以扶阳也。此四阴之卦不曰“小壮”而曰“观”也。四阳之卦有曰“大过”，四阴之卦有曰“小过”者，何阴可以言过而不可以言壮也？然大过之四阳过而居中，小过之四阴过而居外，亦崇阳抑阴之意。</p></li><li><p>梁氏寅曰：“盥而不荐”，设辞以见其洁清之至而不轻自用耳，犹中庸曰“不动而敬，不言而信”。圣人未尝不言不动也，而其敬其信则尤在于未言动之时。故圣人之御天下也，其政教之施民固无不化矣，而其政教未施之时，所以化民者尤有不言之妙焉。盖其笃恭之极，如临大祭而孚诚之念存于中，颙然之容见于外，故下民之望之也，其信从化服自有不知其然矣。</p></li><li><p>蔡氏清曰：平庵项氏云此但以“盥而不荐”象“恭己无为”耳。愚谓“恭己”二字则说得，“无为”二字难通。无为者，圣人德盛而民自化，不待有所为，非不轻自用意也。无为岂可用心乎？虽尧舜亦不能自期于无为。至于神道设教而天下服，则是观之极致，圣人之能事，是则所谓“无为”者。</p></li><li><p>林氏希元曰：“盥将以荐”，岂有不荐之理？曰：“盥而不荐”，特以明敬常在之意耳。“盥而不荐”就祭祀上说，“有孚颙若”亦是就祭祀上说。为“观”之意，则在言表。</p></li></ul><p>象曰：风行地上，观；先王以省方观民设教</p><h3 id="本义-1" tabindex="-1">本义 <a class="header-anchor" href="#本义-1" aria-label="Permalink to “本义”">​</a></h3><p>省方以观民设教，以为观。</p><h3 id="程传-2" tabindex="-1">程传 <a class="header-anchor" href="#程传-2" aria-label="Permalink to “程传”">​</a></h3><p>风行地上，周及庶物，为遨历周览之象。故先王体之为省方之礼，以观民俗而设政教也。天子巡省四方，观视民俗，设为政教，如奢则约之以俭，俭则示之以礼是也。省方观民也，设教为民观也。</p><h3 id="集说-1" tabindex="-1">集说 <a class="header-anchor" href="#集说-1" aria-label="Permalink to “集说”">​</a></h3><ul><li>九家易曰：风行地上，草木必偃，故以省察四方，观视民俗而设其教也。○刘氏牧曰：风行地上，无所不至，散采万国之声诗，省察其俗有不同者，教之使同。</li></ul><p>彖曰：大观在上，顺而巽，中正以观天下</p><h3 id="本义-2" tabindex="-1">本义 <a class="header-anchor" href="#本义-2" aria-label="Permalink to “本义”">​</a></h3><p>以卦体卦德释卦名义。</p><h3 id="程传-3" tabindex="-1">程传 <a class="header-anchor" href="#程传-3" aria-label="Permalink to “程传”">​</a></h3><p>五居尊位，以刚阳中正之德为下所观，其德甚大，故曰“大观在上”。下坤而上巽，是能顺而巽也。五居中正，以巽顺中正之德为观于天下也。</p><h3 id="集说-2" tabindex="-1">集说 <a class="header-anchor" href="#集说-2" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>赵氏彦肃曰：“大观在上”，统谓二阳中正以观天下。</p></li><li><p>杨氏启新曰：“顺以宅心”，尧舜之温恭克让，文王之徽柔懿恭是也；“巽以制事”，通人情、酌物理、随物付物、因时制宜者也。巽德之制也，非巽何以使万事各得其宜。</p></li></ul><p>观盥而不荐，有孚颙若，下观而化也</p><h3 id="本义-3" tabindex="-1">本义 <a class="header-anchor" href="#本义-3" aria-label="Permalink to “本义”">​</a></h3><p>释卦辞。</p><h3 id="程传-4" tabindex="-1">程传 <a class="header-anchor" href="#程传-4" aria-label="Permalink to “程传”">​</a></h3><p>为观之道，严敬如始盥之时，则下民至诚瞻仰而从化也。“不荐”，谓不使诚意少散也。</p><h3 id="集说-3" tabindex="-1">集说 <a class="header-anchor" href="#集说-3" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>虞氏翻曰：“孚”信，“颙”有威，“容”容貌，“容止可观，进退可度”，则下观其德而顺其化。《诗》曰：“颙颙卬卬，如圭如璋”，君德之义也。</p></li><li><p>朱氏震曰：祭之初，迎尸入庙，天子盥手而后酌酒。盥谓之盥，酌酒献尸，尸得之灌地而祭谓之祼。祼之后三献而荐腥，五献而荐熟，谓之荐。盥者，未祼之时，精神专一，诚意未散，不言之信发而为敬顺之貌，颙颙如也。故下观而化，莫不有敬顺之心也。</p></li><li><p>王氏申子曰：观示天下之道，其诚意精一，常如始盥之时，则观感之下莫不从化。盖有不动而敬、不言而信之妙。</p></li></ul><p>观天之神道而四时不忒，圣人以神道设教而天下服矣</p><h3 id="本义-4" tabindex="-1">本义 <a class="header-anchor" href="#本义-4" aria-label="Permalink to “本义”">​</a></h3><p>极言观之道也。四时不忒，天之所以为观也；神道设教，圣人之所以为观也。</p><h3 id="程传-5" tabindex="-1">程传 <a class="header-anchor" href="#程传-5" aria-label="Permalink to “程传”">​</a></h3><p>天道至神，故曰神道。观天之运行，四时无有差忒，则见其神妙。圣人见天道之神，体神道以设教，故天下莫不服也。夫天道至神，故运行四时化育万物无有差忒。至神之道莫可名言，唯圣人黙契体其妙用，设为政教。故天下之人涵泳其德而不知其功，鼓舞其化而莫测其用，自然仰观而戴服。故曰“以神道设教而天下服矣”。</p><h3 id="集说-4" tabindex="-1">集说 <a class="header-anchor" href="#集说-4" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>虞氏翻曰：圣人退藏于密，以神明其德，故设教而天下服矣。</p></li><li><p>王氏弼曰：统说观之为道，不以刑制使物，而以观感化物。神则无形者也，不见天之使四时而四时不忒，不见圣人使百姓而百姓自服也。</p></li><li><p>杨氏时曰：古人所以交神而接人，其道一主于诚。故曰“明则有礼乐，幽则有鬼神”。幽明本无二理，故所以感之者一。圣人以神道设教，所谓神道，诚意而已。诚意，天德也。</p></li><li><p>朱子语类云：圣人以神道设教，即是“盥而不荐”之义。又云，天之神道只是自然运行底道理，四时自然不忒；圣人神道亦是有教人自然观感处。</p></li><li><p>呉氏澄曰：常人以言设教，则有声音；以身设教，则有形迹。圣人妙天道于不测，其应捷如影响。盖所存者神，故所过者化也。</p></li><li><p>杨氏启新曰：圣人设教，诚于此而动于彼，不显之德、笃恭之妙，与上天之载无声无臭者同一机。而其动物之妙、丕变之感，有非人所能测者。故曰“神道设教”。</p></li></ul><p>初六：童观，小人无咎，君子吝</p><h3 id="本义-5" tabindex="-1">本义 <a class="header-anchor" href="#本义-5" aria-label="Permalink to “本义”">​</a></h3><p>卦以观示为义，据九五为主也。爻以观瞻为义，皆观乎九五也。初六阴柔在下，不能远见，童观之象。小人之道，君子之羞也。故其占在小人则无咎，君子得之则可羞矣。</p><h3 id="程传-6" tabindex="-1">程传 <a class="header-anchor" href="#程传-6" aria-label="Permalink to “程传”">​</a></h3><p>六以阴柔之质，居远于阳，是以观见者浅近如童稚然，故曰童观。阳刚中正在上，圣贤之君也。近之则见其道德之盛，所观深远。初乃远之所见，不明如童蒙之观也。小人下民也，所见昏浅，不能识君子之道，乃常分也，不足谓之过咎。若君子而如是，则可鄙吝也。</p><h3 id="集说-5" tabindex="-1">集说 <a class="header-anchor" href="#集说-5" aria-label="Permalink to “集说”">​</a></h3><ul><li>王氏弼曰 ：观之为义，以所见为美者也，故以近尊为尚，远之为吝。</li></ul><p>象曰：初六童观，小人道也</p><h3 id="程传-7" tabindex="-1">程传 <a class="header-anchor" href="#程传-7" aria-label="Permalink to “程传”">​</a></h3><p>所观不明，如童稚，乃小人之分，故曰小人道也。</p><h3 id="集说-6" tabindex="-1">集说 <a class="header-anchor" href="#集说-6" aria-label="Permalink to “集说”">​</a></h3><ul><li>王氏申子曰：卑下而无远见，在凡民为可恕，在君子为可羞。</li></ul><p>六二：窥观，利女贞</p><h3 id="本义-6" tabindex="-1">本义 <a class="header-anchor" href="#本义-6" aria-label="Permalink to “本义”">​</a></h3><p>阴柔居内而观乎外，窥观之象。女子之正也，故其占如此。丈夫得之则非所利矣。</p><h3 id="程传-8" tabindex="-1">程传 <a class="header-anchor" href="#程传-8" aria-label="Permalink to “程传”">​</a></h3><p>二应于五，观于五也。五刚阳中正之道，非二阴暗柔弱所能观见也，故但如窥觇之观耳。窥觇之观虽少见而不能甚明也。二既不能明见刚阳中正之道，则利如女子之贞，虽见之不能甚明而能顺从者，女子之道也。在女子为贞也。二既不能明见九五之道，能如女子之顺从，则不失中正，乃为利也。</p><h3 id="集说-7" tabindex="-1">集说 <a class="header-anchor" href="#集说-7" aria-label="Permalink to “集说”">​</a></h3><ul><li>胡氏炳文曰 ：初位阳，故为童；二位阴，故为女。童观是茫然无所见，小人日用而不知者也。窥观是所见者小而不见全体也。占曰“利女贞”，则非丈夫之所为可知矣。</li></ul><p>象曰：窥观，女贞，亦可丑也</p><h3 id="本义-7" tabindex="-1">本义 <a class="header-anchor" href="#本义-7" aria-label="Permalink to “本义”">​</a></h3><p>在丈夫则为丑也。</p><h3 id="程传-9" tabindex="-1">程传 <a class="header-anchor" href="#程传-9" aria-label="Permalink to “程传”">​</a></h3><p>君子不能观见刚阳中正之大道，而仅窥觇其仿佛，虽能顺从，乃同女子之贞，亦可羞丑也。</p><h3 id="集说-8" tabindex="-1">集说 <a class="header-anchor" href="#集说-8" aria-label="Permalink to “集说”">​</a></h3><ul><li>郭氏忠孝曰：男女吉凶不同，故恒卦曰“妇人吉，夫子凶”，则知利女贞者固为男之丑也。</li></ul><p>六三：观我生，进退</p><h3 id="本义-8" tabindex="-1">本义 <a class="header-anchor" href="#本义-8" aria-label="Permalink to “本义”">​</a></h3><p>我生，我之所行也。六三居下之上，可进可退，故不观九五而独观己所行之通塞，以为进退。占者宜自审也。</p><h3 id="程传-10" tabindex="-1">程传 <a class="header-anchor" href="#程传-10" aria-label="Permalink to “程传”">​</a></h3><p>三居非其位，处顺之极，能顺时以进退者也。若居当其位，则无进退之义也。观我生，我之所生谓动作施为出于己者，观其所生而随宜进退，所以处虽非正而未至失道也。随时进退，求不失道，故无悔咎，以能顺也。</p><h3 id="集说-9" tabindex="-1">集说 <a class="header-anchor" href="#集说-9" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>孔氏颖达曰 ：三居下体之极，是有可进之时；又居上体之下，复是可退之地。远则不为童观，近则未为观国，居在进退之处，可以自观时。可则进，时不可则退，故曰“观我生进退”也。</p></li><li><p>刘氏牧曰 ：自观其道，应于时则进，不应于时则退。</p></li><li><p>朱子语类云 ：六三之“观我生进退”者，事君则观其言听计从，治民则观其政教可行，膏泽可下，可以见自家所施之当否而为进退。</p></li><li><p>王氏申子曰 ：三处下之上，上之下，故有进退之象。君子进退常观乎时，今不观乎时而观我生者，盖九五方以阳刚中正观示天下，则时不待观也，但观吾之所有以为进退可也。</p></li><li><p>胡氏炳文曰 ：他卦三不中多不善，二居中多善，而观以远近为义，故如此。诸爻皆欲观五，惟近者得之。六四最近，故可决于进；六三上下之间，可进可退之地，故不必观五，但观我所为而为之进退。本义谓占者宜自审，盖当进退之际，惟当自审其所为何如耳。</p></li></ul><p>象曰：观我生，进退未失道也</p><h3 id="程传-11" tabindex="-1">程传 <a class="header-anchor" href="#程传-11" aria-label="Permalink to “程传”">​</a></h3><p>观己之生而进退以顺乎宜，故未至于失道也。</p><h3 id="案" tabindex="-1">案 <a class="header-anchor" href="#案" aria-label="Permalink to “案”">​</a></h3><p>道即进退之道，量而后入，则不失乎进退之道矣。</p><p>六四：观国之光，利用宾于王</p><h3 id="本义-9" tabindex="-1">本义 <a class="header-anchor" href="#本义-9" aria-label="Permalink to “本义”">​</a></h3><p>六四最近于五，故有此象。其占为利于朝觐仕进也。</p><h3 id="程传-12" tabindex="-1">程传 <a class="header-anchor" href="#程传-12" aria-label="Permalink to “程传”">​</a></h3><p>观莫明于近五。以阳刚中正居尊位，圣贤之君也。四切近之，观见其道，故云“观国之光”。观见国之盛德光辉也。不指君之身而云国者，在人君而言，岂止观其行一身乎？当观天下之政化，则人君之道德可见矣。四虽阴柔而巽体居正，切近于五，观见而能顺从者也。利用宾于王，夫圣明在上，则怀抱才德之人皆愿进于朝廷，辅戴之以匡济天下。四既观见人君之德，国家之治，光华盛美，所宜宾于王朝，效其智力，上辅于君以施泽天下，故云“利用宾于王”也。古者有贤德之人，则人君宾礼之，故士之仕进于王朝，则谓之宾。</p><h3 id="集说-10" tabindex="-1">集说 <a class="header-anchor" href="#集说-10" aria-label="Permalink to “集说”">​</a></h3><ul><li>刘氏定之曰 ：九五大君，观己所为以仪型天下。初居阳而去五远，所观不明如童子；二居阴而去五远，所观不明如女子。惟四得正而去五近，所观最明，故曰“观光宾王”。盖诸爻皆就五取义也。</li></ul><p>象曰：观国之光，尚宾也</p><h3 id="程传-13" tabindex="-1">程传 <a class="header-anchor" href="#程传-13" aria-label="Permalink to “程传”">​</a></h3><p>君子怀负才业，志在乎兼善天下。然有卷怀自守者，盖时无明君，莫能用其道，不得已也，岂君子之志哉？故孟子曰：“中天下而立，定四海之民，君子乐之。”既观见国之盛德光华，古人所谓非常之遇也，所以志愿登进王朝以行其道，故云“观国之光，尚宾也”。尚谓志尚，其志意愿慕宾于王朝也。</p><h3 id="集说-11" tabindex="-1">集说 <a class="header-anchor" href="#集说-11" aria-label="Permalink to “集说”">​</a></h3><ul><li>杨氏简曰：言其国贵尚宾贤，可以进也。</li></ul><p>九五：观我生，君子无咎</p><h3 id="本义-10" tabindex="-1">本义 <a class="header-anchor" href="#本义-10" aria-label="Permalink to “本义”">​</a></h3><p>九五阳刚中正以居尊位，其下四阴仰而观之，君子之象也。故戒居此位得此占者，当观巳所行，必其阳刚中正亦如是焉，则得无咎也。</p><h3 id="程传-14" tabindex="-1">程传 <a class="header-anchor" href="#程传-14" aria-label="Permalink to “程传”">​</a></h3><p>九五居人君之位，时之治乱，俗之美恶，系乎已而己。观已之生，若天下之俗皆君子矣，则是已之所为政化善也，乃无咎矣。若天下之俗未合君子之道，则是已之所为政治未善，不能免于咎也。</p><h3 id="集说-12" tabindex="-1">集说 <a class="header-anchor" href="#集说-12" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>孔氏颖达曰 ：九五居尊，为观之主，四海之内由我而化。我教化善，则天下有君子之风；教化不善，则天下著小人之俗。故观民以察我道，有君子之风者，则无咎也。</p></li><li><p>朱子语类云 ：九五之“观我生”，如观风俗之美恶，臣民之从违，可以见自家所施之善恶。</p></li><li><p>王氏申子曰 ：五阳刚中正，居尊位以观天下，此君子之道也。天下皆仰而观之，在五又当观巳之所行，必一出于君子之道，然后可以立身于无过之地，故曰“观我生，君子无咎”。</p></li></ul><p>象曰：观我生，观民也</p><h3 id="本义-11" tabindex="-1">本义 <a class="header-anchor" href="#本义-11" aria-label="Permalink to “本义”">​</a></h3><p>此夫子以义言之，明人君观己所行，不但一身之得失，又当观民德之善否以自省察也。</p><h3 id="程传-15" tabindex="-1">程传 <a class="header-anchor" href="#程传-15" aria-label="Permalink to “程传”">​</a></h3><p>我生出于己者，人君欲观己之施为善否，当观于民。民俗善则政化善也。王弼云：“观民以察己之道是也。”</p><h3 id="集说-13" tabindex="-1">集说 <a class="header-anchor" href="#集说-13" aria-label="Permalink to “集说”">​</a></h3><ul><li>胡氏瑗曰：观流则可以知源，观影则可以知表，观民则可以知己政之得失也。</li></ul><p>上九：观其生，君子无咎</p><h3 id="本义-12" tabindex="-1">本义 <a class="header-anchor" href="#本义-12" aria-label="Permalink to “本义”">​</a></h3><p>上九阳刚居尊位之上，虽不当事任而亦为下所观，故其戒辞略与五同，但以我为其小有主宾之异耳。</p><h3 id="程传-16" tabindex="-1">程传 <a class="header-anchor" href="#程传-16" aria-label="Permalink to “程传”">​</a></h3><p>上九以阳刚之德处于上，为下之所观，而不当位，是贤人君子不在于位而道德为天下所观仰者也。观其生，观其所生也，谓出于己者德业行义也。既为天下所观仰，故自观其所生，若皆君子矣，则无过咎也。苟未君子，则何以使人观仰矜式，是其咎也。</p><h3 id="集说-14" tabindex="-1">集说 <a class="header-anchor" href="#集说-14" aria-label="Permalink to “集说”">​</a></h3><ul><li>王氏弼曰 ：观我生，自观其道者也；观其生，为民所观者也。不在于位，最处上极高尚，其志为天下所观者也。处天下所观之地，可不慎乎？故君子德见，乃得无咎。</li></ul><h3 id="案-1" tabindex="-1">案 <a class="header-anchor" href="#案-1" aria-label="Permalink to “案”">​</a></h3><p>上九“观其生”似只是承九五之义而终言之尔。盖九五正当君位，故曰“我”。上非君位，而但以君道论之，故曰其辞与九五无异者，正所以见圣人省身察己始终如一之心。故象传发明之曰：“志未平也。”</p><p>总论</p><ul><li><p>朱子语类 ：问：观卦阴盛而不言凶咎。 曰：此卦取义不同。盖阴虽盛于下，而九五之君乃当正位，故只取为观于下之义，而不取阴盛之象也。 问：观六爻，一爻胜似一爻，岂所居之位愈高则所见愈大耶？ 曰：上二爻意自别，下四爻是所据之位愈近则所见愈亲切底意思。</p></li><li><p>问：观卦阴盛而不言凶咎。 曰：此卦取义不同。盖阴虽盛于下，而九五之君乃当正位，故只取为观于下之义，而不取阴盛之象也。</p></li><li><p>问：观六爻，一爻胜似一爻，岂所居之位愈高则所见愈大耶？ 曰：上二爻意自别，下四爻是所据之位愈近则所见愈亲切底意思。</p></li></ul><p>象曰：观其生，志未平也</p><h3 id="本义-13" tabindex="-1">本义 <a class="header-anchor" href="#本义-13" aria-label="Permalink to “本义”">​</a></h3><p>志未平，言虽不得位，未可忘戒惧也。</p><h3 id="程传-17" tabindex="-1">程传 <a class="header-anchor" href="#程传-17" aria-label="Permalink to “程传”">​</a></h3><p>虽不在位，然以人观其德用为仪法，故当自慎省。观其所生常不失于君子，则人不失所望而化之矣。不可以不在于位，故安然放意无所事也。是其志意未得安也，故云“志未平也”。平谓安宁也。</p><h3 id="集说-15" tabindex="-1">集说 <a class="header-anchor" href="#集说-15" aria-label="Permalink to “集说”">​</a></h3><ul><li>陆氏希声曰：民之善恶由我德化，其志未平，忧民之未化也。</li></ul>',120)])])}const m=e(h,[["render",p]]);export{b as __pageData,m as default};
